import { create } from 'zustand';
import { Task, columns } from '../types';

interface TaskStore {
  tasks: Task[];
  addTask: (task: Omit<Task, 'id' | 'status'>) => void;
  updateTask: (id: string, updates: Partial<Task>) => void;
  deleteTask: (id: string) => void;
  moveTask: (taskId: string, newStatus: Task['status']) => void;
  toggleDarkMode: () => void;
  isDarkMode: boolean;
}

const STORAGE_KEY = 'task-management-app-tasks';
const DARK_MODE_KEY = 'task-management-app-dark-mode';

export const useTaskStore = create<TaskStore>((set, get) => ({
  tasks: JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]'),
  isDarkMode: JSON.parse(localStorage.getItem(DARK_MODE_KEY) || 'false'),

  addTask: (task) => {
    const newTask: Task = { ...task, id: crypto.randomUUID(), status: 'todo' };
    set((state) => ({ tasks: [...state.tasks, newTask] }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify([...state.tasks, newTask]));
  },

  updateTask: (id, updates) => {
    set((state) => ({
      tasks: state.tasks.map((t) => (t.id === id ? { ...t, ...updates } : t)),
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(get().tasks));
  },

  deleteTask: (id) => {
    set((state) => ({
      tasks: state.tasks.filter((t) => t.id !== id),
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(get().tasks));
  },

  moveTask: (taskId, newStatus) => {
    set((state) => ({
      tasks: state.tasks.map((t) =>
        t.id === taskId ? { ...t, status: newStatus } : t
      ),
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(get().tasks));
  },

  toggleDarkMode: () => {
    set((state) => {
      const newMode = !state.isDarkMode;
      localStorage.setItem(DARK_MODE_KEY, JSON.stringify(newMode));
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return { isDarkMode: newMode };
    });
  },
}));
