import { useDrag, useDrop } from 'react-dnd';
import { Task } from '../types';

export const useTaskDrag = () => {
  const { tasks, moveTask } = useTaskStore();

  const ref = useDrag({
    type: 'TASK',
    item: (task: Task) => ({
      ...task,
      columnId: task.status === 'todo' ? 'todo' : task.status === 'inprogress' ? 'inprogress' : 'done',
    }),
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  return { ref, tasks, moveTask };
};

export const useTaskDrop = (columnId: string) => {
  const { tasks, moveTask } = useTaskStore();

  const dropRef = useDrop({
    accept: 'TASK',
    hover: (draggedItem: { id: string; columnId: string }) => {
      if (draggedItem.columnId !== columnId) {
        const task = tasks.find((t) => t.id === draggedItem.id);
        if (task) {
          moveTask(draggedItem.id, columnId === 'todo' ? 'todo' : columnId === 'inprogress' ? 'inprogress' : 'done');
        }
      }
    },
    collect: (monitor) => ({
      isOver: monitor.isOver(),
    }),
  });

  return { ref: dropRef, isOver };
};
