import { Task } from '../types';
import { useState } from 'react';
import { useTaskStore } from '../store/taskStore';

interface TaskCardProps {
  task: Task;
}

export const TaskCard = ({ task }: TaskCardProps) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(task.title);
  const [editDescription, setEditDescription] = useState(task.description);
  const [editDueDate, setEditDueDate] = useState(task.dueDate);
  const [editPriority, setEditPriority] = useState(task.priority);

  const { updateTask, deleteTask, moveTask } = useTaskStore();

  const handleSave = () => {
    updateTask(task.id, {
      title: editTitle,
      description: editDescription,
      dueDate: editDueDate,
      priority: editPriority,
    });
    setIsEditing(false);
  };

  const handleDelete = () => {
    deleteTask(task.id);
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  if (isEditing) {
    return (
      <div className="bg-white dark:bg-secondary-800 rounded-lg shadow-md p-4 space-y-3">
        <input
          type="text"
          value={editTitle}
          onChange={(e) => setEditTitle(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 dark:border-secondary-700 rounded-md bg-white dark:bg-secondary-900 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500"
          placeholder="Task title"
        />
        <textarea
          value={editDescription}
          onChange={(e) => setEditDescription(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 dark:border-secondary-700 rounded-md bg-white dark:bg-secondary-900 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500"
          placeholder="Description"
          rows={2}
        />
        <input
          type="date"
          value={editDueDate}
          onChange={(e) => setEditDueDate(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 dark:border-secondary-700 rounded-md bg-white dark:bg-secondary-900 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500"
        />
        <select
          value={editPriority}
          onChange={(e) => setEditPriority(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 dark:border-secondary-700 rounded-md bg-white dark:bg-secondary-900 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500"
        >
          <option value="low">Low Priority</option>
          <option value="medium">Medium Priority</option>
          <option value="high">High Priority</option>
        </select>
        <div className="flex gap-2">
          <button
            onClick={handleSave}
            className="px-4 py-2 bg-primary-600 text-white rounded-md hover:bg-primary-700 transition-colors"
          >
            Save
          </button>
          <button
            onClick={() => setIsEditing(false)}
            className="px-4 py-2 bg-gray-200 dark:bg-secondary-700 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-secondary-600 transition-colors"
          >
            Cancel
          </button>
        </div>
      </div>
    );
  }

  const daysUntilDue = (() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(task.dueDate + 'T00:00:00');
    const diffTime = due.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  })();

  const isOverdue = daysUntilDue < 0;

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      className="bg-white dark:bg-secondary-800 rounded-lg shadow-md p-4 cursor-move hover:shadow-lg transition-shadow group"
    >
      <div className="flex justify-between items-start gap-2">
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-gray-900 dark:text-gray-100 truncate">
            {task.title}
          </h3>
          {task.description && (
            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
              {task.description}
            </p>
          )}
        </div>
        <div className="flex flex-col items-end gap-1">
          <span className={`px-2 py-1 text-xs font-medium rounded-full ${priorityColors[task.priority]}`}>
            {task.priority}
          </span>
        </div>
      </div>

      {task.dueDate && (
        <div className={`mt-3 text-xs ${isOverdue ? 'text-red-600 dark:text-red-400 font-semibold' : 'text-gray-500 dark:text-gray-400'}`}>
          Due: {task.dueDate}
          {isOverdue && ' (Overdue)'}
        </div>
      )}

      <div className="flex gap-2 mt-3 pt-3 border-t border-gray-200 dark:border-secondary-700 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={() => setIsEditing(true)}
          className="px-3 py-1 text-xs bg-gray-100 dark:bg-secondary-700 text-gray-700 dark:text-gray-300 rounded hover:bg-gray-200 dark:hover:bg-secondary-600 transition-colors"
        >
          Edit
