import { TaskFormModal } from './components/TaskFormModal';
import { Header } from './components/Header';
import { Board } from './components/Board';
import { useTaskStore } from './store/taskStore';

function App() {
  const [editingTask, setEditingTask] = useState<{ task: null | { id: string } }>({ task: null });

  const handleAddTask = () => {
    setEditingTask({ task: null });
  };

  const handleEditTask = (task: { id: string }) => {
    setEditingTask({ task });
  };

  const handleCloseModal = () => {
    setEditingTask({ task: null });
  };

  const { tasks } = useTaskStore();
  const taskCount = tasks.length;
  const doneCount = tasks.filter((t) => t.status === 'done').length;
  const progress = taskCount > 0 ? Math.round((doneCount / taskCount) * 100) : 0;

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-secondary-950 transition-colors">
      <Header />

      {/* Progress Bar */}
      <div className="bg-white dark:bg-secondary-800 border-b border-gray-200 dark:border-secondary-700 px-6 py-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-32 h-2 bg-gray-200 dark:bg-secondary-700 rounded-full overflow-hidden">
              <div 
                className="h-full bg-primary-500 transition-all duration-300"
                style={{ width: `${progress}%` }}
              />
            </div>
            <span className="text-sm text-gray-600 dark:text-gray-400">
              {progress}% complete ({doneCount}/{taskCount})
            </span>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto">
        <Board />
      </main>

      {editingTask.task && (
        <TaskFormModal
          task={editingTask.task.task ? { id: editingTask.task.task.id } : null}
          onClose={handleCloseModal}
        />
      )}
    </div>
  );
}

export default App;
